1	//! # xerj-compress
2	//!
3	//! Compression engine for the xerj search engine.
4	//!
5	//! Provides:
6	//! - [`codec`] — Codec trait with LZ4, Zstd, and passthrough implementations
7	//! - [`block`] — Block-level compression for 128-document segments
8	//! - [`dictionary`] — Dictionary encoding for repeated string values
9	//! - [`field_codec`] — Intelligent automatic field encoding engine
10	
11	pub mod block;
12	pub mod codec;
13	pub mod dictionary;
14	pub mod field_codec;
15	
16	pub use block::{BlockReader, BlockWriter};
17	pub use codec::{get_codec, Codec, CompressionLevel, Lz4Codec, NoneCodec, ZstdCodec};
18	pub use dictionary::{DictionaryDecoder, DictionaryEncoder};
19	pub use field_codec::{FieldAnalyzer, FieldEncoding, TimestampFormat};
20	
21	pub use xerj_common::Result;
22

1	//! Dictionary encoding for repeated string values.
2	//!
3	//! Ideal for low-cardinality fields like log levels, hostnames, and status
4	//! codes. Values are mapped to compact u16 IDs, reducing storage from ~20
5	//! bytes per value to 2 bytes after the dictionary is built.
6	
7	use std::collections::HashMap;
8	use xerj_common::XerjError;
9	
10	/// Result alias for dictionary operations.
11	pub type Result<T> = std::result::Result<T, XerjError>;
12	
13	/// Maximum number of distinct values in a single dictionary.
14	///
15	/// u16::MAX entries — keeps IDs in 2 bytes.
16	pub const MAX_DICT_ENTRIES: usize = 65_535;
17	
18	// ─────────────────────────────────────────────────────────────────────────────
19	// DictionaryEncoder
20	// ─────────────────────────────────────────────────────────────────────────────
21	
22	/// Encodes string values as compact u16 dictionary IDs.
23	///
24	/// # Usage
25	///
26	/// 1. Call [`build_from_sample`] with a representative set of values.
27	/// 2. Call [`encode`] for each value to get its ID.
28	/// 3. Serialize the dictionary alongside the encoded data for decoding.
29	#[derive(Debug, Clone)]
30	pub struct DictionaryEncoder {
31	    /// value → ID
32	    map: HashMap<String, u16>,
33	    /// Ordered vocabulary — index is the ID.
34	    vocab: Vec<String>,
35	}
36	
37	impl DictionaryEncoder {
38	    /// Create an empty encoder. Call [`build_from_sample`] before encoding.
39	    pub fn new() -> Self {
40	        Self {
41	            map: HashMap::new(),
42	            vocab: Vec::new(),
43	        }
44	    }
45	
46	    /// Build the dictionary from a slice of sample values.
47	    ///
48	    /// Values are sorted by frequency (most common first) so that common
49	    /// values get the smallest IDs, which can compress better downstream.
50	    pub fn build_from_sample<'a, I>(&mut self, samples: I)
51	    where
52	        I: IntoIterator<Item = &'a str>,
53	    {
54	        // Count frequencies
55	        let mut freq: HashMap<&str, usize> = HashMap::new();
56	        for s in samples {
57	            *freq.entry(s).or_insert(0) += 1;
58	        }
59	
60	        // Sort by descending frequency, then alphabetically for stability
61	        let mut entries: Vec<(&str, usize)> = freq.into_iter().collect();
62	        entries.sort_unstable_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
63	
64	        self.map.clear();
65	        self.vocab.clear();
66	
67	        for (value, _) in entries.into_iter().take(MAX_DICT_ENTRIES) {
68	            let id = self.vocab.len() as u16;
69	            self.vocab.push(value.to_owned());
70	            self.map.insert(value.to_owned(), id);
71	        }
72	    }
73	
74	    /// Encode a value, returning its dictionary ID.
75	    ///
76	    /// Returns `None` if the value is not in the dictionary (out-of-vocabulary).
77	    /// Callers should handle OOV values by storing raw bytes or a fallback ID.
78	    pub fn encode(&self, value: &str) -> Option<u16> {
79	        self.map.get(value).copied()
80	    }
81	
82	    /// Encode with insert — adds the value if not present, fails if dict is full.
83	    pub fn encode_or_insert(&mut self, value: &str) -> Result<u16> {
84	        if let Some(&id) = self.map.get(value) {
85	            return Ok(id);
86	        }
87	        if self.vocab.len() >= MAX_DICT_ENTRIES {
88	            return Err(XerjError::resource_exhausted(format!(
89	                "dictionary full ({MAX_DICT_ENTRIES} entries)"
90	            )));
91	        }
92	        let id = self.vocab.len() as u16;
93	        self.vocab.push(value.to_owned());
94	        self.map.insert(value.to_owned(), id);
95	        Ok(id)
96	    }
97	
98	    /// Number of entries in the dictionary.
99	    pub fn len(&self) -> usize {
100	        self.vocab.len()
101	    }
102	
103	    pub fn is_empty(&self) -> bool {
104	        self.vocab.is_empty()
105	    }
106	
107	    /// Return the ordered vocabulary for serialization.
108	    pub fn vocab(&self) -> &[String] {
109	        &self.vocab
110	    }
111	
112	    /// Serialize the dictionary to bytes (length-prefixed UTF-8 strings).
113	    ///
114	    /// Format:
115	    /// ```text
116	    /// u32 LE  — entry count
117	    /// for each entry:
118	    ///   u16 LE — byte length of string
119	    ///   bytes  — UTF-8 string data
120	    /// ```
121	    pub fn serialize(&self) -> Vec<u8> {
122	        let mut out = Vec::new();
123	        let count = self.vocab.len() as u32;
124	        out.extend_from_slice(&count.to_le_bytes());
125	        for s in &self.vocab {
126	            let bytes = s.as_bytes();
127	            let len = bytes.len() as u16;
128	            out.extend_from_slice(&len.to_le_bytes());
129	            out.extend_from_slice(bytes);
130	        }
131	        out
132	    }
133	}
134	
135	impl Default for DictionaryEncoder {
136	    fn default() -> Self {
137	        Self::new()
138	    }
139	}
140	
141	// ─────────────────────────────────────────────────────────────────────────────
142	// DictionaryDecoder
143	// ─────────────────────────────────────────────────────────────────────────────
144	
145	/// Decodes u16 dictionary IDs back to their original string values.
146	#[derive(Debug, Clone)]
147	pub struct DictionaryDecoder {
148	    vocab: Vec<String>,
149	}
150	
151	impl DictionaryDecoder {
152	    /// Build from the encoder's vocabulary.
153	    pub fn from_vocab(vocab: Vec<String>) -> Self {
154	        Self { vocab }
155	    }
156	
157	    /// Build from an encoder directly.
158	    pub fn from_encoder(encoder: &DictionaryEncoder) -> Self {
159	        Self {
160	            vocab: encoder.vocab().to_vec(),
161	        }
162	    }
163	
164	    /// Deserialize from bytes produced by [`DictionaryEncoder::serialize`].
165	    pub fn deserialize(data: &[u8]) -> Result<Self> {
166	        if data.len() < 4 {
167	            return Err(XerjError::internal("dictionary data too short"));
168	        }
169	        let count = u32::from_le_bytes(data[0..4].try_into().unwrap()) as usize;
170	        let mut pos = 4usize;
171	        let mut vocab = Vec::with_capacity(count);
172	
173	        for _ in 0..count {
174	            if pos + 2 > data.len() {
175	                return Err(XerjError::internal("dictionary truncated at string length"));
176	            }
177	            let slen = u16::from_le_bytes(data[pos..pos + 2].try_into().unwrap()) as usize;
178	            pos += 2;
179	            if pos + slen > data.len() {
180	                return Err(XerjError::internal("dictionary truncated at string data"));
181	            }
182	            let s = std::str::from_utf8(&data[pos..pos + slen])
183	                .map_err(|e| XerjError::internal(format!("dictionary utf8: {e}")))?
184	                .to_owned();
185	            vocab.push(s);
186	            pos += slen;
187	        }
188	
189	        Ok(Self { vocab })
190	    }
191	
192	    /// Decode a u16 ID to the original string.
193	    ///
194	    /// Returns `None` if the ID is out of range.
195	    pub fn decode(&self, id: u16) -> Option<&str> {
196	        self.vocab.get(id as usize).map(String::as_str)
197	    }
198	
199	    /// Number of entries.
200	    pub fn len(&self) -> usize {
201	        self.vocab.len()
202	    }
203	
204	    pub fn is_empty(&self) -> bool {
205	        self.vocab.is_empty()
206	    }
207	}
