213	#[cfg(test)]
214	mod tests {
215	    use super::*;
216	
217	    #[test]
218	    fn encode_decode_roundtrip() {
219	        let samples = ["INFO", "ERROR", "WARN", "INFO", "INFO", "DEBUG", "ERROR"];
220	        let mut encoder = DictionaryEncoder::new();
221	        encoder.build_from_sample(samples.iter().copied());
222	
223	        // INFO should be ID 0 (most frequent)
224	        assert_eq!(encoder.encode("INFO"), Some(0));
225	        assert_eq!(encoder.encode("MISSING"), None);
226	
227	        let decoder = DictionaryDecoder::from_encoder(&encoder);
228	        assert_eq!(decoder.decode(0), Some("INFO"));
229	    }
230	
231	    #[test]
232	    fn serialize_deserialize() {
233	        let samples = ["alpha", "beta", "gamma", "alpha", "beta", "alpha"];
234	        let mut encoder = DictionaryEncoder::new();
235	        encoder.build_from_sample(samples.iter().copied());
236	
237	        let bytes = encoder.serialize();
238	        let decoder = DictionaryDecoder::deserialize(&bytes).unwrap();
239	
240	        assert_eq!(decoder.len(), encoder.len());
241	        // alpha is most frequent — should be ID 0
242	        let id = encoder.encode("alpha").unwrap();
243	        assert_eq!(decoder.decode(id), Some("alpha"));
244	    }
245	
246	    #[test]
247	    fn encode_or_insert_grows_dict() {
248	        let mut encoder = DictionaryEncoder::new();
249	        let id0 = encoder.encode_or_insert("first").unwrap();
250	        let id1 = encoder.encode_or_insert("second").unwrap();
251	        let id0b = encoder.encode_or_insert("first").unwrap();
252	
253	        assert_eq!(id0, id0b, "same value must produce same ID");
254	        assert_ne!(id0, id1);
255	        assert_eq!(encoder.len(), 2);
256	    }
257	
258	    #[test]
259	    fn log_levels_realistic() {
260	        let levels = ["TRACE", "DEBUG", "INFO", "WARN", "ERROR", "FATAL"];
261	        let mut encoder = DictionaryEncoder::new();
262	        encoder.build_from_sample(levels.iter().copied());
263	
264	        let bytes = encoder.serialize();
265	        let decoder = DictionaryDecoder::deserialize(&bytes).unwrap();
266	
267	        for level in &levels {
268	            let id = encoder.encode(level).expect("level should be in dict");
269	            assert_eq!(decoder.decode(id), Some(*level));
270	        }
271	    }
272	}
