1	//! Intelligent automatic field encoding for xerj.
2	//!
3	//! Analyzes a column of values and selects the most storage-efficient encoding
4	//! based on field name hints and statistical properties of the data.
5	//!
6	//! # Encoding selection ladder
7	//!
8	//! 1. **Field-name fast path** — well-known names (`status`, `timestamp`, `ip`, …)
9	//!    map directly to their optimal encoding without any data scanning.
10	//! 2. **Cardinality check** — ≤16 unique → [`FieldEncoding::BitsetEnum`];
11	//!    ≤256 unique → [`FieldEncoding::Dictionary`].
12	//! 3. **Type probes** — integer / float / timestamp / IP / URL / boolean heuristics.
13	//! 4. **Fallback** — [`FieldEncoding::RawString`].
14	//!
15	//! # Example
16	//!
17	//! ```rust
18	//! use xerj_compress::field_codec::{FieldAnalyzer, FieldEncoding};
19	//!
20	//! let statuses = vec!["200", "200", "404", "500", "200", "301"];
21	//! let analyzer = FieldAnalyzer::new(1024);
22	//! let encoding = analyzer.analyze("status", &statuses);
23	//! println!("bytes/value: {:.2}", encoding.bytes_per_value());
24	//! ```
25	
26	use std::collections::{HashMap, HashSet};
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// TimestampFormat
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	/// Detected timestamp wire format.
33	#[derive(Debug, Clone, PartialEq, Eq)]
34	pub enum TimestampFormat {
35	    /// `2024-01-15T12:34:56Z` or with timezone offset
36	    Iso8601,
37	    /// `[10/Jan/2024:12:34:56 +0000]`
38	    ApacheCommon,
39	    /// `2024/01/15 12:34:56`
40	    NginxDefault,
41	    /// Unix epoch seconds — `1705312496`
42	    EpochSeconds,
43	    /// Unix epoch milliseconds — `1705312496000`
44	    EpochMillis,
45	    /// Any other recognizable pattern
46	    Custom(String),
47	}
48	
49	// ─────────────────────────────────────────────────────────────────────────────
50	// FieldEncoding — the chosen representation for a single column
51	// ─────────────────────────────────────────────────────────────────────────────
52	
53	/// Detected field encoding — chosen automatically from data statistics.
54	///
55	/// Each variant stores the fully encoded column data so it can be serialized
56	/// or used for in-memory analytics directly.
57	#[derive(Debug, Clone)]
58	pub enum FieldEncoding {
59	    /// HTTP status codes, log levels — tiny fixed set (≤16 values).
60	    ///
61	    /// Stored as a 4-bit index + one bitmap per dictionary entry.
62	    /// Filtering `status == 200` returns a pre-built bitmap in O(1).
63	    BitsetEnum {
64	        /// Ordered dictionary (max 16 entries).
65	        values: Vec<String>,
66	        /// `bitmap[i]` is a packed bitset where bit `j` is set when
67	        /// document `j` holds `values[i]`.
68	        bitmap: Vec<Vec<u8>>,
69	    },
70	
71	    /// Timestamps — delta-of-delta encoding.
72	    ///
73	    /// Apache/Nginx/ISO formats are auto-detected; all values are stored
74	    /// as microsecond deltas, typically 1–2 bytes each in practice.
75	    DeltaTimestamp {
76	        /// First timestamp in microseconds since the Unix epoch.
77	        base_us: i64,
78	        /// Detected wire format.
79	        format: TimestampFormat,
80	        /// Delta-of-delta values (delta between consecutive deltas).
81	        deltas: Vec<i64>,
82	    },
83	
84	    /// IP addresses — packed u32 for IPv4.
85	    ///
86	    /// 4 bytes vs 7–15 bytes as a string. Enables fast CIDR range queries
87	    /// via bitwise mask comparison on the packed integer.
88	    PackedIp {
89	        /// IPv4 addresses as big-endian u32.
90	        values: Vec<u32>,
91	    },
92	
93	    /// URL paths — template + extracted variables.
94	    ///
95	    /// `/api/users/123` is stored as template `/api/users/{}` plus the
96	    /// variable `"123"`, reducing storage for repetitive URL trees.
97	    UrlTemplate {
98	        /// Deduplicated templates, e.g. `["/api/users/{}", "/static/{}"]`.
99	        templates: Vec<String>,
100	        /// Per-document index into `templates`.
101	        template_ids: Vec<u16>,
102	        /// Per-document list of extracted variable segments.
103	        variables: Vec<Vec<String>>,
104	    },
105	
106	    /// Small integers — varint encoding.
107	    ///
108	    /// For content-length, port numbers, counts. Numbers 0–127 take 1 byte;
109	    /// 128–16383 take 2 bytes; etc.
110	    Varint {
111	        /// Raw values — varint-encoded when serialized.
112	        values: Vec<u64>,
113	    },
114	
115	    /// Low-cardinality strings — dictionary encoding.
116	    ///
117	    /// For HTTP methods, log levels, hostnames, service names.
118	    /// Per-document cost: 2 bytes (u16 ID) instead of the full string.
119	    Dictionary {
120	        /// Unique values ordered by first appearance.
121	        dict: Vec<String>,
122	        /// Per-document index into `dict`.
123	        ids: Vec<u16>,
124	    },
125	
126	    /// High-cardinality strings — raw storage.
127	    ///
128	    /// Falls back to this when no smarter encoding applies.
129	    RawString { values: Vec<String> },
130	
131	    /// Booleans — bit-packed (8 values per byte).
132	    Bitpacked {
133	        /// Packed bits — bit `j` of byte `j/8` is document `j`'s value.
134	        bits: Vec<u8>,
135	        /// Number of logical boolean values stored.
136	        count: usize,
137	    },
138	
139	    /// Floating point with fixed precision — multiply by 10^N, store as varint.
140	    ///
141	    /// `12.34` with scale 2 → `1234`.  Typically 2 bytes vs 8 bytes (f64).
142	    FixedPrecision {
143	        /// The exponent `N` such that `stored_value = original * 10^N`.
144	        scale: u32,
145	        /// Scaled integer values.
146	        values: Vec<i64>,
147	    },
148	}
149	
150	// ─────────────────────────────────────────────────────────────────────────────
151	// FieldEncoding — size estimation
152	// ─────────────────────────────────────────────────────────────────────────────
153	
154	impl FieldEncoding {
155	    /// Estimated average bytes per stored value (data only, excluding headers).
156	    pub fn bytes_per_value(&self) -> f64 {
157	        let (total, count) = match self {
158	            FieldEncoding::BitsetEnum { bitmap, .. } => {
159	                let n_docs: usize = bitmap.first().map(|b| b.len() * 8).unwrap_or(0);
160	                // 4-bit index per document + bitmap overhead
161	                let bitmap_bytes: usize = bitmap.iter().map(|b| b.len()).sum();
162	                let ids_bytes = n_docs.div_ceil(2); // 4-bit index per doc
163	                (bitmap_bytes + ids_bytes, n_docs.max(1))
164	            }
165	            FieldEncoding::DeltaTimestamp { deltas, .. } => {
166	                // Average varint: small deltas typically fit in 1–2 bytes
167	                let bytes: usize = deltas.iter().map(|d| varint_signed_len(*d)).sum();
168	                (bytes, deltas.len().max(1))
169	            }
170	            FieldEncoding::PackedIp { values } => (values.len() * 4, values.len().max(1)),
171	            FieldEncoding::UrlTemplate {
172	                template_ids,
173	                variables,
174	                ..
175	            } => {
176	                let ids_bytes = template_ids.len() * 2;
177	                let var_bytes: usize = variables
178	                    .iter()
179	                    .flat_map(|v| v.iter())
180	                    .map(|s| s.len() + 1)
181	                    .sum();
182	                (ids_bytes + var_bytes, template_ids.len().max(1))
183	            }
184	            FieldEncoding::Varint { values } => {
185	                let bytes: usize = values.iter().map(|v| varint_unsigned_len(*v)).sum();
186	                (bytes, values.len().max(1))
187	            }
188	            FieldEncoding::Dictionary { ids, .. } => (ids.len() * 2, ids.len().max(1)),
189	            FieldEncoding::RawString { values } => {
190	                let bytes: usize = values.iter().map(|s| s.len()).sum();
191	                (bytes, values.len().max(1))
192	            }
193	            FieldEncoding::Bitpacked { count, .. } => (*count, count.saturating_mul(8).max(1)),
194	            FieldEncoding::FixedPrecision { values, .. } => {
195	                let bytes: usize = values.iter().map(|v| varint_signed_len(*v)).sum();
196	                (bytes, values.len().max(1))
197	            }
198	        };
199	        if count == 0 {
200	            return 0.0;
201	        }
202	        total as f64 / count as f64
203	    }
204	
205	    /// Total bytes used by the encoded column data.
206	    pub fn total_bytes(&self) -> usize {
207	        match self {
208	            FieldEncoding::BitsetEnum { bitmap, .. } => bitmap.iter().map(|b| b.len()).sum(),
209	            FieldEncoding::DeltaTimestamp { deltas, .. } => {
210	                deltas.iter().map(|d| varint_signed_len(*d)).sum()
211	            }
212	            FieldEncoding::PackedIp { values } => values.len() * 4,
213	            FieldEncoding::UrlTemplate {
214	                template_ids,
215	                variables,
216	                templates,
217	            } => {
218	                let tmpl_bytes: usize = templates.iter().map(|t| t.len()).sum();
219	                let ids_bytes = template_ids.len() * 2;
220	                let var_bytes: usize = variables
221	                    .iter()
222	                    .flat_map(|v| v.iter())
223	                    .map(|s| s.len() + 1)
224	                    .sum();
225	                tmpl_bytes + ids_bytes + var_bytes
226	            }
227	            FieldEncoding::Varint { values } => {
228	                values.iter().map(|v| varint_unsigned_len(*v)).sum()
229	            }
230	            FieldEncoding::Dictionary { dict, ids } => {
231	                let dict_bytes: usize = dict.iter().map(|s| s.len()).sum();
232	                dict_bytes + ids.len() * 2
233	            }
234	            FieldEncoding::RawString { values } => values.iter().map(|s| s.len()).sum(),
235	            FieldEncoding::Bitpacked { bits, .. } => bits.len(),
236	            FieldEncoding::FixedPrecision { values, .. } => {
237	                values.iter().map(|v| varint_signed_len(*v)).sum()
238	            }
239	        }
240	    }
241	
242	    /// Number of documents stored.
243	    pub fn doc_count(&self) -> usize {
244	        match self {
245	            FieldEncoding::BitsetEnum { bitmap, .. } => {
246	                bitmap.first().map(|b| b.len() * 8).unwrap_or(0)
247	            }
248	            FieldEncoding::DeltaTimestamp { deltas, .. } => deltas.len() + 1,
249	            FieldEncoding::PackedIp { values } => values.len(),
250	            FieldEncoding::UrlTemplate { template_ids, .. } => template_ids.len(),
251	            FieldEncoding::Varint { values } => values.len(),
252	            FieldEncoding::Dictionary { ids, .. } => ids.len(),
253	            FieldEncoding::RawString { values } => values.len(),
254	            FieldEncoding::Bitpacked { count, .. } => *count,
255	            FieldEncoding::FixedPrecision { values, .. } => values.len(),
256	        }
257	    }
258	
259	    /// Compression ratio relative to storing raw UTF-8 strings.
260	    ///
261	    /// A ratio of 4.0 means the encoding uses 4× less space than raw strings.
262	    pub fn compression_ratio_vs_raw(&self) -> f64 {
263	        let bpv = self.bytes_per_value();
264	        if bpv == 0.0 {
265	            return 1.0;
266	        }
267	        // We don't have the original strings at this point, so we use
268	        // a conservative estimate for the raw baseline based on encoding type.
269	        let raw_bpv = match self {
270	            FieldEncoding::BitsetEnum { .. } => 3.0, // e.g. "200", "GET"
271	            FieldEncoding::DeltaTimestamp { .. } => 25.0, // typical timestamp string
272	            FieldEncoding::PackedIp { .. } => 14.0,  // "192.168.100.200" avg
273	            FieldEncoding::UrlTemplate { .. } => 30.0, // typical URL path
274	            FieldEncoding::Varint { .. } => 6.0,     // content-length as string
275	            FieldEncoding::Dictionary { .. } => 12.0, // hostname / service name
276	            FieldEncoding::RawString { .. } => bpv,  // already raw
277	            FieldEncoding::Bitpacked { .. } => 4.5,  // "true" / "false"
278	            FieldEncoding::FixedPrecision { .. } => 6.0, // "12.34"
279	        };
280	        raw_bpv / bpv
281	    }
282	}
