547	    /// Build a [`FieldEncoding::Varint`] from a column of integer strings.
548	    pub fn encode_as_varint(&self, values: &[&str]) -> FieldEncoding {
549	        let nums: Vec<u64> = values
550	            .iter()
551	            .map(|v| v.parse::<u64>().unwrap_or(0))
552	            .collect();
