577	    /// Build a [`FieldEncoding::Bitpacked`] from a column of boolean strings.
578	    pub fn encode_as_bitpacked(&self, values: &[&str]) -> FieldEncoding {
579	        let count = values.len();
580	        let mut bits = vec![0u8; count.div_ceil(8)];
581	        for (i, v) in values.iter().enumerate() {
582	            let is_true = *v == "true" || *v == "1";
583	            if is_true {
584	                bits[i / 8] |= 1 << (i % 8);
585	            }
586	        }
587	        FieldEncoding::Bitpacked { bits, count }
588	    }
