590	    /// Build a [`FieldEncoding::FixedPrecision`] from a column of float strings.
591	    ///
592	    /// Detects the minimum scale (decimal places) required to represent all
593	    /// values exactly, then multiplies by `10^scale` and stores as `i64`.
594	    pub fn encode_as_fixed_precision(&self, values: &[&str]) -> FieldEncoding {
595	        let scale = detect_decimal_scale(values);
596	        let multiplier = 10_i64.pow(scale);
597	        let scaled: Vec<i64> = values
598	            .iter()
599	            .map(|v| {
600	                v.parse::<f64>()
601	                    .map(|f| (f * multiplier as f64).round() as i64)
602	                    .unwrap_or(0)
603	            })
604	            .collect();
605	        FieldEncoding::FixedPrecision {
606	            scale,
607	            values: scaled,
608	        }
609	    }
