613	    /// Heuristic: does the sample look like it contains timestamps?
614	    fn looks_like_timestamp(&self, sample: &[&str]) -> bool {
615	        if sample.is_empty() {
616	            return false;
617	        }
618	        let threshold = (sample.len() * 8 / 10).max(1); // 80%
619	        let matched = sample
620	            .iter()
621	            .filter(|v| detect_timestamp_format_single(v) != TimestampLikelihood::None)
622	            .count();
623	        matched >= threshold
624	    }
625	}
