637	#[derive(PartialEq)]
638	enum TimestampLikelihood {
639	    None,
640	    Likely,
641	}
642	
643	/// Classify a single value for timestamp likelihood without full parsing.
644	fn detect_timestamp_format_single(v: &str) -> TimestampLikelihood {
645	    // ISO 8601: starts with 4 digits + '-'
646	    if v.len() >= 10
647	        && v.as_bytes().iter().take(4).all(|b| b.is_ascii_digit())
648	        && v.as_bytes().get(4) == Some(&b'-')
649	    {
650	        return TimestampLikelihood::Likely;
651	    }
652	    // Apache common: starts with '['
653	    if v.starts_with('[') && v.len() > 20 {
654	        return TimestampLikelihood::Likely;
655	    }
656	    // Nginx: `YYYY/MM/DD`
657	    if v.len() >= 10
658	        && v.as_bytes().iter().take(4).all(|b| b.is_ascii_digit())
659	        && v.as_bytes().get(4) == Some(&b'/')
660	    {
661	        return TimestampLikelihood::Likely;
662	    }
663	    // Epoch seconds (10 digits) or millis (13 digits)
664	    if (v.len() == 10 || v.len() == 13) && v.as_bytes().iter().all(|b| b.is_ascii_digit()) {
665	        return TimestampLikelihood::Likely;
666	    }
667	    TimestampLikelihood::None
668	}
669	
670	/// Detect the dominant timestamp format across a sample.
671	fn detect_timestamp_format(values: &[&str]) -> TimestampFormat {
672	    for v in values {
673	        let v = v.trim();
674	        if v.starts_with('[') {
675	            return TimestampFormat::ApacheCommon;
676	        }
677	        if v.len() >= 10
678	            && v.as_bytes().iter().take(4).all(|b| b.is_ascii_digit())
679	            && v.as_bytes().get(4) == Some(&b'/')
680	        {
681	            return TimestampFormat::NginxDefault;
682	        }
683	        if v.len() >= 10
684	            && v.as_bytes().iter().take(4).all(|b| b.is_ascii_digit())
685	            && v.as_bytes().get(4) == Some(&b'-')
686	        {
687	            return TimestampFormat::Iso8601;
688	        }
689	        if let Ok(n) = v.parse::<i64>() {
690	            if n > 1_000_000_000_000 {
691	                return TimestampFormat::EpochMillis;
692	            }
693	            return TimestampFormat::EpochSeconds;
694	        }
695	    }
696	    TimestampFormat::EpochSeconds
697	}
