699	/// Parse a timestamp string to microseconds since the Unix epoch.
700	///
701	/// Returns `None` on parse failure — callers substitute `0` as a sentinel.
702	fn parse_timestamp_us(v: &str, format: &TimestampFormat) -> Option<i64> {
703	    let v = v.trim();
704	    match format {
705	        TimestampFormat::EpochSeconds => v.parse::<i64>().ok().map(|s| s * 1_000_000),
706	        TimestampFormat::EpochMillis => v.parse::<i64>().ok().map(|ms| ms * 1_000),
707	        TimestampFormat::Iso8601 => parse_iso8601_us(v),
708	        TimestampFormat::ApacheCommon => parse_apache_us(v),
709	        TimestampFormat::NginxDefault => parse_nginx_us(v),
710	        TimestampFormat::Custom(_) => None,
711	    }
712	}
