803	/// Days since Unix epoch (1970-01-01) using the proleptic Gregorian calendar.
804	fn days_since_epoch(year: i64, month: i64, day: i64) -> Option<i64> {
805	    if !((1..=12).contains(&month) && (1..=31).contains(&day)) {
806	        return None;
807	    }
808	    // Rata Die algorithm
809	    let m = if month <= 2 { month + 9 } else { month - 3 };
810	    let y = if month <= 2 { year - 1 } else { year };
811	    let era = y.div_euclid(400);
812	    let yoe = y.rem_euclid(400);
813	    let doy = (153 * m + 2) / 5 + day - 1;
814	    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
815	    let rata_die = era * 146097 + doe;
816	    // Days from 0000-03-01 to 1970-01-01 = 719468
817	    Some(rata_die - 719468)
818	}
