843	/// Returns `true` if `v` is a valid dotted-decimal IPv4 address.
844	fn is_ipv4(v: &str) -> bool {
845	    parse_ipv4(v).is_some()
846	}
847	
848	/// Parse a dotted-decimal IPv4 string to a packed u32.
849	///
850	/// `192.168.1.1` → `(192 << 24) | (168 << 16) | (1 << 8) | 1`
851	pub fn parse_ipv4(v: &str) -> Option<u32> {
852	    let mut octets = v.split('.');
853	    let a: u32 = octets.next()?.parse().ok()?;
854	    let b: u32 = octets.next()?.parse().ok()?;
855	    let c: u32 = octets.next()?.parse().ok()?;
856	    let d: u32 = octets.next()?.parse().ok()?;
857	    if octets.next().is_some() {
858	        return None; // extra segments
859	    }
860	    if a > 255 || b > 255 || c > 255 || d > 255 {
861	        return None;
862	    }
863	    Some((a << 24) | (b << 16) | (c << 8) | d)
864	}
865	
866	/// Check whether a packed IP falls inside a CIDR block.
867	///
868	/// ```rust
869	/// use xerj_compress::field_codec::{parse_ipv4, ip_in_cidr};
870	/// let ip = parse_ipv4("10.0.0.15").unwrap();
871	/// assert!(ip_in_cidr(ip, parse_ipv4("10.0.0.0").unwrap(), 24));
872	/// ```
873	pub fn ip_in_cidr(ip: u32, network: u32, prefix_len: u32) -> bool {
874	    if prefix_len == 0 {
875	        return true;
876	    }
877	    if prefix_len > 32 {
878	        return false;
879	    }
880	    let mask = !0u32 << (32 - prefix_len);
881	    (ip & mask) == (network & mask)
882	}
