885	// Helpers — URL template extraction
886	// ─────────────────────────────────────────────────────────────────────────────
887	
888	/// Split a URL path into a (template, variables) pair.
889	///
890	/// Numeric segments and UUID-like segments are replaced with `{}`.
891	///
892	/// ```
893	/// // "/api/users/123" → ("/api/users/{}", ["123"])
894	/// // "/static/js/app.abc123.js" → ("/static/js/{}", ["app.abc123.js"])
895	/// ```
896	fn extract_url_template(url: &str) -> (String, Vec<String>) {
897	    // Split off query string and fragment
898	    let path = url
899	        .split('?')
900	        .next()
901	        .unwrap_or(url)
902	        .split('#')
903	        .next()
904	        .unwrap_or(url);
905	
906	    let mut template_parts: Vec<&str> = Vec::new();
907	    let mut vars: Vec<String> = Vec::new();
908	
909	    for segment in path.split('/') {
910	        if is_variable_segment(segment) {
911	            template_parts.push("{}");
912	            vars.push(segment.to_string());
913	        } else {
914	            template_parts.push(segment);
915	        }
916	    }
917	
918	    (template_parts.join("/"), vars)
919	}
920	
921	/// Returns `true` if a URL path segment should be treated as a variable
922	/// (and replaced with `{}` in the template).
923	fn is_variable_segment(seg: &str) -> bool {
924	    if seg.is_empty() {
925	        return false;
926	    }
927	    // Pure integer
928	    if seg.bytes().all(|b| b.is_ascii_digit()) && !seg.is_empty() {
929	        return true;
930	    }
931	    // UUID: 8-4-4-4-12 hex groups
932	    if is_uuid_like(seg) {
933	        return true;
934	    }
935	    // Hex string ≥ 8 chars (commit hash, object ID, content hash in filenames)
936	    if seg.len() >= 8 && seg.bytes().all(|b| b.is_ascii_hexdigit()) {
937	        return true;
938	    }
939	    // File with a content hash (e.g. "app.abc123def456.js") —
940	    // contains a dot and a hex-dominated component between dots
941	    let parts: Vec<&str> = seg.split('.').collect();
942	    if parts.len() >= 3 {
943	        // At least one middle segment is a hex hash
944	        for p in &parts[1..parts.len() - 1] {
945	            if p.len() >= 6 && p.bytes().all(|b| b.is_ascii_hexdigit()) {
946	                return true;
947	            }
948	        }
949	    }
950	    false
951	}
952	
953	/// Heuristic UUID detection (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx).
954	fn is_uuid_like(s: &str) -> bool {
955	    let bytes = s.as_bytes();
956	    if bytes.len() != 36 {
957	        return false;
958	    }
959	    bytes[8] == b'-'
960	        && bytes[13] == b'-'
961	        && bytes[18] == b'-'
962	        && bytes[23] == b'-'
963	        && bytes.iter().enumerate().all(|(i, &b)| {
964	            if i == 8 || i == 13 || i == 18 || i == 23 {
965	                b == b'-'
966	            } else {
967	                b.is_ascii_hexdigit()
968	            }
969	        })
970	}
