975	
976	/// Detect the minimum number of decimal places needed to represent all values
977	/// in the sample exactly (up to a maximum of 6 decimal places).
978	fn detect_decimal_scale(values: &[&str]) -> u32 {
979	    let mut max_scale: u32 = 0;
980	    for v in values {
981	        if let Some(dot_pos) = v.find('.') {
982	            let decimal_places = v.len() - dot_pos - 1;
983	            max_scale = max_scale.max(decimal_places as u32);
984	            if max_scale >= 6 {
985	                return 6;
986	            }
987	        }
988	    }
989	    max_scale.min(6)
990	}
