1221	                assert_eq!(values.len(), 16, "dictionary must stay within 16 slots");
1222	                assert!(
1223	                    values.contains(&"__other__".to_string()),
1224	                    "overflow must add an __other__ sentinel"
1225	                );
1226	                assert_eq!(bitmap.len(), values.len());
1227	
1228	                // Every document sets exactly one bit — nothing is dropped.
1229	                let total_set_bits: u32 = bitmap
1230	                    .iter()
1231	                    .flat_map(|b| b.iter())
1232	                    .map(|byte| byte.count_ones())
1233	                    .sum();
1234	                assert_eq!(
1235	                    total_set_bits as usize,
1236	                    refs.len(),
1237	                    "every doc must map to exactly one bit (no value dropped)"
